class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, fillForward=False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, fillForward=False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, fillForward=False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, fillForward=False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, fillForward=False).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        has_spy = data.Bars.ContainsKey(self.spy)
        has_aapl = data.Bars.ContainsKey(self.aapl)
        has_ibm = data.Bars.ContainsKey(self.ibm)
        has_bac = data.Bars.ContainsKey(self.bac)
        has_aig = data.Bars.ContainsKey(self.aig)

        spy_cross_above = False
        spy_cross_below = False

        if has_spy:
            spy_close = float(data.Bars[self.spy].Close)

            if self.spy_sma.IsReady and self.previous_spy_close is not None:
                current_sma = float(self.spy_sma.Current.Value)

                if self.previous_spy_sma is not None:
                    spy_cross_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_close > current_sma
                    )
                    spy_cross_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_close < current_sma
                    )

                self.previous_spy_sma = current_sma

            self.previous_spy_close = spy_close

        if has_aapl:
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if self.IsWarmingUp:
            return

        if not (has_spy and has_aapl and has_ibm and has_bac and has_aig):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        if self.strategy_a_lot > 0 and spy_cross_below:
            quantity = self.strategy_a_lot
            if self._submit_order(self.spy, -quantity, "Strategy A Sell"):
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and float(self.aapl_rsi.Current.Value) > 60:
            quantity = self.strategy_b_lot
            if self._submit_order(self.aapl, -quantity, "Strategy B Sell"):
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_cross_above:
            spy_close = float(data.Bars[self.spy].Close)
            quantity = int(math.floor(
                0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close
            ))

            if quantity > 0 and self._submit_order(
                self.spy, quantity, "Strategy A Buy"
            ):
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            aapl_close = float(data.Bars[self.aapl].Close)

            if float(self.Portfolio.Cash) >= 20000:
                quantity = int(math.floor(20000 / aapl_close))

                if quantity > 0 and self._submit_order(
                    self.aapl, quantity, "Strategy B Buy"
                ):
                    self.strategy_b_lot = quantity

    def _submit_order(self, symbol, quantity, tag):
        if quantity == 0:
            return False

        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Invalid,
            OrderStatus.Canceled
        )

