class ExactStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending = {
            "A": False,
            "B": False
        }

        self.order_info = {}
        self.last_processed_date = None

    def OnData(self, data):
        current_date = self.Time.date()

        if self.last_processed_date == current_date:
            return

        self.last_processed_date = current_date
        bars = data.Bars

        spy_cross_above = False
        spy_cross_below = False
        aapl_red_three_days = False

        if self._has_bar(bars, self.spy):
            spy_close = float(bars[self.spy].Close)
            current_spy_sma = (
                float(self.spy_sma.Current.Value)
                if self.spy_sma.IsReady
                else None
            )

            if (
                current_spy_sma is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close is not None
            ):
                spy_cross_above = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_close > current_spy_sma
                )

                spy_cross_below = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_close < current_spy_sma
                )

            self.previous_spy_close = spy_close

            if current_spy_sma is not None:
                self.previous_spy_sma = current_spy_sma

        if self._has_bar(bars, self.aapl):
            aapl_close = float(bars[self.aapl].Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close
            aapl_red_three_days = self.aapl_red_streak >= 3

        if not all(self._has_bar(bars, symbol) for symbol in self.symbols):
            return

        aapl_rsi_above_60 = (
            self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60
        )

        if (
            self.lots["A"] > 0
            and not self.pending["A"]
            and spy_cross_below
        ):
            self._submit_order(
                "A",
                self.spy,
                -self.lots["A"],
                "Strategy A liquidation"
            )

        if (
            self.lots["B"] > 0
            and not self.pending["B"]
            and aapl_rsi_above_60
        ):
            self._submit_order(
                "B",
                self.aapl,
                -self.lots["B"],
                "Strategy B liquidation"
            )

        if (
            self.lots["A"] == 0
            and not self.pending["A"]
            and spy_cross_above
        ):
            spy_close = float(bars[self.spy].Close)
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(floor(target_value / spy_close))

            if quantity > 0:
                self._submit_order(
                    "A",
                    self.spy,
                    quantity,
                    "Strategy A buy"
                )

        if (
            self.lots["B"] == 0
            and not self.pending["B"]
            and aapl_red_three_days
        ):
            aapl_close = float(bars[self.aapl].Close)

            if float(self.Portfolio.Cash) >= 20000:
                quantity = int(floor(20000 / aapl_close))

                if quantity > 0:
                    self._submit_order(
                        "B",
                        self.aapl,
                        quantity,
                        "Strategy B buy"
                    )

    def OnOrderEvent(self, order_event):
        strategy = self.order_info.get(order_event.OrderId)

        if strategy is None:
            tag = str(getattr(order_event, "Tag", ""))

            if tag.startswith("PrivateLot:A:"):
                strategy = "A"
            elif tag.startswith("PrivateLot:B:"):
                strategy = "B"
            elif order_event.Symbol == self.spy:
                strategy = "A"
            elif order_event.Symbol == self.aapl:
                strategy = "B"

        if strategy is None:
            return

        if order_event.Status in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            self.lots[strategy] += int(order_event.FillQuantity)

            if self.lots[strategy] < 0:
                self.lots[strategy] = 0

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending[strategy] = False
            self.order_info.pop(order_event.OrderId, None)

    def _submit_order(self, strategy, symbol, quantity, description):
        if quantity == 0:
            return

        self.pending[strategy] = True
        tag = "PrivateLot:{}:{}".format(
            strategy,
            "buy" if quantity > 0 else "sell"
        )

        try:
            ticket = self.MarketOrder(symbol, quantity, tag=tag)
        except Exception:
            self.pending[strategy] = False
            return

        self.order_info[ticket.OrderId] = strategy

        if ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending[strategy] = False
            self.order_info.pop(ticket.OrderId, None)

    def _has_bar(self, bars, symbol):
        try:
            return bars.ContainsKey(symbol)
        except AttributeError:
            return symbol in bars

