                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_close < current_spy_sma
                    )

                self.previous_spy_sma = current_spy_sma
            else:
                self.previous_spy_sma = None

            self.previous_spy_close = spy_close
        else:
            self.previous_spy_close = None
            self.previous_spy_sma = None

        if has_aapl:
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close
            aapl_buy_signal = self.aapl_red_streak >= 3

            if self.aapl_rsi.IsReady:
                aapl_sell_signal = float(self.aapl_rsi.Current.Value) > 60
        else:
            self.previous_aapl_close = None
            self.aapl_red_streak = 0

        if not has_all_bars:
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        if (
            self.strategy_a_lot > 0
            and not self.strategy_a_sell_pending
            and spy_sell_signal
        ):
            self.strategy_a_sell_pending = True
            self.MarketOrder(
                self.spy,
                -self.strategy_a_lot,
                tag="A_SELL"
            )

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_sell_pending
            and aapl_sell_signal
        ):
            self.strategy_b_sell_pending = True
            self.MarketOrder(
                self.aapl,
                -self.strategy_b_lot,
                tag="B_SELL"
            )

        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_buy_pending
            and spy_buy_signal
        ):
            spy_close = float(data.Bars[self.spy].Close)
            target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
            quantity = int(target_value / spy_close)

            if quantity > 0:
                self.strategy_a_buy_pending = True
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="A_BUY"
                )

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_buy_pending
            and aapl_buy_signal
        ):
            aapl_close = float(data.Bars[self.aapl].Close)
            available_cash = float(self.Portfolio.Cash)

            if available_cash >= 20000:
                quantity = int(20000 / aapl_close)

                if quantity > 0:
                    self.strategy_b_buy_pending = True
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="B_BUY"
